 * The scanner. Turns UTF-8 source text into a flat list of tokens, or throws
 * a LexError carrying the 1-based line/column of the first offending
 * character and a short reason string.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCT_2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT_1 = new Set(['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.'])

const HEX_RE = /[0-9a-fA-F]/
const DEC_RE = /[0-9]/
const BIN_RE = /[01]/
const OCT_RE = /[0-7]/
const LETTER_RE = /[A-Za-z_]/
const ALNUM_RE = /[A-Za-z0-9_]/

export class LexError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

/**
 * Scans `source` and returns an array of `{ line, col, kind, text }` tokens,
 * where `text` is the source text for every kind except `string` and
 * `rawstring`, whose `text` is the decoded value.
 */
export function scan(source) {
  const chars = Array.from(source)
  const n = chars.length
  const positions = new Array(n + 1)
  {
    let line = 1
    let col = 1
    for (let idx = 0; idx < n; idx++) {
      positions[idx] = { line, col }
      const c = chars[idx]
      if (c === '\n') {
        line += 1
        col = 1
      } else if (c === '\t') {
        col = Math.floor((col - 1) / 4) * 4 + 5
      } else {
        col += 1
      }
    }
    positions[n] = { line, col }
  }

  let i = 0
  const cur = () => chars[i]
  const peek = (k) => chars[i + k]
  const curPos = () => positions[i]

  function fail(pos, reason) {
    throw new LexError(pos.line, pos.col, reason)
  }

  function skipLineComment() {
    i += 2
    while (i < n && cur() !== '\n') i += 1
  }

  function skipBlockComment() {
    const openPos = curPos()
    i += 2
    let depth = 1
    while (depth > 0) {
      if (i >= n) fail(openPos, 'unterminated block comment')
      if (cur() === '/' && peek(1) === '*') {
        depth += 1
        i += 2
      } else if (cur() === '*' && peek(1) === '/') {
        depth -= 1
        i += 2
      } else {
        i += 1
      }
    }
  }

  function consumeDigits(isDigit) {
    let count = 0
    while (i < n) {
      if (isDigit(cur())) {
        i += 1
        count += 1
      } else if (cur() === '_' && count > 0 && i + 1 < n && isDigit(chars[i + 1])) {
        i += 1
      } else {
        break
      }
    }
    return count
  }

  function scanNumber() {
    const startPos = curPos()
    const start = i
    let prefixed = false
    let hasDigits = true

    if (cur() === '0' && (peek(1) === 'x' || peek(1) === 'X' || peek(1) === 'b' || peek(1) === 'B' || peek(1) === 'o' || peek(1) === 'O')) {
      const marker = peek(1).toLowerCase()
      const isDigit = marker === 'x' ? HEX_RE : marker === 'b' ? BIN_RE : OCT_RE
      i += 2
      prefixed = true
      hasDigits = consumeDigits((c) => isDigit.test(c)) > 0
    } else {
      consumeDigits((c) => DEC_RE.test(c))
      if (cur() === '.' && i + 1 < n && DEC_RE.test(peek(1))) {
        i += 1
        consumeDigits((c) => DEC_RE.test(c))
      }
      if (cur() === 'e' || cur() === 'E') {
        const hasSign = peek(1) === '+' || peek(1) === '-'
        const digitIdx = hasSign ? i + 2 : i + 1
        if (digitIdx < n && DEC_RE.test(chars[digitIdx])) {
          i += 1
          if (hasSign) i += 1
          consumeDigits((c) => DEC_RE.test(c))
        }
      }
    }

    let extended = false
    while (i < n && ALNUM_RE.test(cur())) {
      i += 1
      extended = true
    }

    const text = chars.slice(start, i).join('')
    if (extended || (prefixed && !hasDigits)) {
      fail(startPos, `invalid number ${text}`)
    }
    return { line: startPos.line, col: startPos.col, kind: 'number', text }
  }

  function scanString() {
    const startPos = curPos()
    i += 1
    let value = ''
    while (true) {
      if (i >= n) fail(startPos, 'unterminated string')
      const c = cur()
      if (c === '"') {
        i += 1
        break
      }
      if (c === '\n') fail(curPos(), 'newline in string')
      if (c === '\\') {
        const escPos = curPos()
        i += 1
        if (i >= n) fail(startPos, 'unterminated string')
        const e = cur()
        if (e === 'n') {
          value += '\n'
          i += 1
        } else if (e === 't') {
          value += '\t'
          i += 1
        } else if (e === 'r') {
          value += '\r'
          i += 1
        } else if (e === '\\') {
          value += '\\'
          i += 1
        } else if (e === '"') {
          value += '"'
          i += 1
        } else if (e === '0') {
          value += '\0'
          i += 1
        } else if (e === 'x') {
          const d1 = peek(1)
          const d2 = peek(2)
          if (d1 !== undefined && d2 !== undefined && HEX_RE.test(d1) && HEX_RE.test(d2)) {
            value += String.fromCharCode(parseInt(d1 + d2, 16))
            i += 3
