            fail(escPos, 'invalid escape \\x')
          }
        } else if (e === 'u') {
          if (peek(1) !== '{') fail(escPos, 'invalid escape \\u')
          let j = i + 2
          let hex = ''
          while (j < n && chars[j] !== '}' && chars[j] !== '\n') {
