            j += 1
          }
          if (hex.length === 0 || j >= n || chars[j] !== '}') fail(escPos, 'invalid escape \\u')
          const cp = parseInt(hex, 16)
          if (cp > 0x10ffff) fail(escPos, 'invalid escape \\u')
          value += String.fromCodePoint(cp)
          i = j + 1
        } else {
          fail(escPos, `invalid escape \\${e}`)
        }
      } else {
        value += c
        i += 1
      }
    }
    return { line: startPos.line, col: startPos.col, kind: 'string', text: JSON.stringify(value) }
  }

  function scanRawString() {
    const startPos = curPos()
    i += 2
    let value = ''
    while (true) {
      if (i >= n) fail(startPos, 'unterminated string')
      const c = cur()
      if (c === '"') {
        i += 1
        break
      }
      value += c
      i += 1
    }
    return { line: startPos.line, col: startPos.col, kind: 'rawstring', text: JSON.stringify(value) }
  }

  function scanIdent() {
    const startPos = curPos()
    const start = i
    i += 1
    while (i < n && ALNUM_RE.test(cur())) i += 1
    const text = chars.slice(start, i).join('')
    return { line: startPos.line, col: startPos.col, kind: KEYWORDS.has(text) ? 'keyword' : 'ident', text }
  }

  function scanPunct() {
    const startPos = curPos()
    const two = cur() + (peek(1) ?? '')
    if (PUNCT_2.includes(two)) {
      i += 2
      return { line: startPos.line, col: startPos.col, kind: 'punct', text: two }
    }
    if (PUNCT_1.has(cur())) {
      const text = cur()
      i += 1
      return { line: startPos.line, col: startPos.col, kind: 'punct', text }
    }
    fail(startPos, `unexpected character ${cur()}`)
  }

  const tokens = []
  while (true) {
    while (true) {
      while (i < n && (cur() === ' ' || cur() === '\t' || cur() === '\r' || cur() === '\n')) i += 1
      if (i < n && cur() === '/' && peek(1) === '/') {
        skipLineComment()
        continue
      }
      if (i < n && cur() === '/' && peek(1) === '*') {
        skipBlockComment()
        continue
      }
      break
    }
    if (i >= n) break

    const c = cur()
    if (c === '"') {
      tokens.push(scanString())
    } else if (c === 'r' && peek(1) === '"') {
      tokens.push(scanRawString())
    } else if (LETTER_RE.test(c)) {
      tokens.push(scanIdent())
    } else if (DEC_RE.test(c)) {
      tokens.push(scanNumber())
    } else {
      tokens.push(scanPunct())
    }
  }
  return tokens
}
"}

